initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Upsert Entities with Response Status Code set to 201     and
        Batch Upsert Entities with Response Body set to an array of created entities ids     and
        Query Entities with Updated Entities set to '${updated_entities}' valid entities
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/upsert?options=${update_option}'
        method set to 'POST'
        Request batch upsert operation over entity from filename '@{entities_to_be_upserted}' with update_option set to 'update' and Content-Type set to 'application/ld+json'
}

